def generate_nominal_rows(n, fan_status=None):
    # Generate n rows of nominal data
    base_row = dict(NOMINAL_SENSOR_TEMPLATE)
    if fan_status is None or fan_status == 'open':
        base_row['Fan Status'] = 1
    elif fan_status == 'closed':
        base_row['Fan Status'] = 0
    final_rows = []
    for i in range(n):
        row = base_row.copy()
        row['tick'] = i
        final_rows.append(row)
    return final_rows


def resolve_anomalies_for_tick(sensor_row, fan_status, anomalies_list):
    """
    Determine which anomalies are active for a single tick.

    Strategy:
    - Collect active sensors per module (IHab, HALO)
    - For CDRA and BFS: check cross-module (fan on) or per-module (fan off)
    - For all others: always module-specific
    - Only flag the most complex anomaly that fully covers active sensors,
      suppressing simpler ones whose sensors are a strict subset.
    - When fan is off, suppression is evaluated per-module independently.

    Returns a dict of {anomaly_name: 0 or 1} for all anomalies in anomalies_list.
    """

    # NOTE: Updated on 08/26/26 to capture both types of VCCR failure signatures
    CROSS_MODULE_ANOMALIES = {"VCCR Particulate Filter Saturation", "VCCR Sorbent Bed Saturation", "OGA Failure"}

    # NOTE: NEW CODE ON 09/16/2026
    # --- 1. Collect all off-nominal sensors across the full model, not just
    # sensors that appear in some known anomaly's symptom list. This is what
    # lets Unknown Anomaly fire on a genuinely novel signature, since a sensor
    # can be off-nominal (1=warning or 2=critical) without belonging to any
    # ANOMALY_SYMPTOMS entry.
    all_active = {s: sensor_row.get(s, 0) for s in ALL_SENSOR_NAMES if sensor_row.get(s, 0) >= 1}

    # # --- 1. Collect all active sensors ---
    # all_active = {}
    # for anom_info in ANOMALY_SYMPTOMS.values():
    #     for sensor, threshold in anom_info["sensors"]:
    #         val = sensor_row.get(sensor, 0)
    #         if val >= threshold:
    #             all_active[sensor] = val

    # --- 2. Helper: get required sensors for an anomaly, optionally filtered by module ---
    def required_sensors(anom_name, module=None):
        """
        Return the set of required sensor names for anom_name.
        If module is 'IHab' or 'HALO', restrict to sensors for that module only.
        """
        sensors = ANOMALY_SYMPTOMS[anom_name]["sensors"]
        if module is not None:
            return {s for s, _ in sensors if s.endswith(f"({module})")}
        return {s for s, _ in sensors}

    def all_symptoms_present(anom_name, module=None):
        """
        Return True if all required sensors for anom_name are active.
        If module is specified, only check sensors for that module.
        A required sensor not belonging to the specified module is ignored
        (treated as satisfied), allowing per-module partial checks.
        """
        for sensor, threshold in ANOMALY_SYMPTOMS[anom_name]["sensors"]:
            if module is not None and not sensor.endswith(f"({module})"):
                continue
            if sensor_row.get(sensor, 0) < threshold:
                return False
        return True

    # --- 3a. Cross-module anomalies (CDRA, BFS) ---
    # Fan ON:  all sensors in both modules must be active simultaneously
    # Fan OFF: symptoms in EITHER module alone are sufficient to flag
    flagged = set()

    for anom_name in CROSS_MODULE_ANOMALIES:
        if anom_name not in ANOMALY_SYMPTOMS:
            continue

        if fan_status == 'off':
            if all_symptoms_present(anom_name, module='IHab') or \
               all_symptoms_present(anom_name, module='HALO'):
                flagged.add(anom_name)
        else:
            if all_symptoms_present(anom_name):
                flagged.add(anom_name)

    # --- 3b. Module-specific anomalies ---
    for anom_name in ANOMALY_SYMPTOMS:
        if anom_name in CROSS_MODULE_ANOMALIES:
            continue
        if all_symptoms_present(anom_name):
            flagged.add(anom_name)

    # --- 4. Suppress simpler anomalies ---
    # An anomaly A is suppressed by anomaly B if:
    #   - B is also flagged
    #   - required_sensors(A) is a strict subset of required_sensors(B)
    #   - When fan is OFF, this subset check is done per-module independently:
    #       A is suppressed only if its per-module sensor set is a strict subset
    #       of B's per-module sensor set for the SAME module.
    #     This prevents cross-module suppression when atmospheres are isolated.
    #   - When fan is ON, the full sensor sets are compared (original behavior).
    #
    # Example (fan off, IHab only active):
    #   Emergency O2 (IHab) requires {low ppO2_IHab}
    #   BFS requires {low ppO2_IHab, high ppCO2_IHab} for IHab module
    #   Since {low ppO2_IHab} ⊂ {low ppO2_IHab, high ppCO2_IHab}, Emergency O2 is suppressed.
    #
    # Example (fan off, only IHab active, CDRA fired from IHab sensors):
    #   Emergency O2 (IHab) IHab-sensors = {low ppO2_IHab}
    #   CDRA IHab-sensors = {low ppO2_IHab, high ppCO2_IHab, high Humidity_IHab}
    #   {low ppO2_IHab} ⊂ CDRA's IHab sensors → Emergency O2 (IHab) suppressed. ✓
    #
    # Example (fan off, HALO humidity absent, BFS fired from IHab):
    #   Excess CO2 (HALO) HALO-sensors = {high ppCO2_HALO}
    #   BFS HALO-sensors = {low ppO2_HALO, high ppCO2_HALO}
    #   BFS didn't fire from HALO (ppO2_HALO absent), so no suppression of Excess CO2 (HALO). ✓

    to_suppress = set()
    flagged_list = list(flagged)

    for anom_a in flagged_list:
        for anom_b in flagged_list:
            if anom_a == anom_b:
                continue

            if fan_status == 'off':
                # Check suppression independently per module.
                # A is suppressed by B if, for every module where A has required sensors,
                # A's sensors in that module are a strict subset of B's sensors in that module,
                # AND B actually fired based on that module's sensors.
                suppressed_by_b = False
                for module in ('IHab', 'HALO'):
                    req_a_mod = required_sensors(anom_a, module=module)
                    req_b_mod = required_sensors(anom_b, module=module)

                    if not req_a_mod:
                        # A has no sensors in this module, skip
                        continue

                    # B must have fired from this module's sensors specifically
                    b_fires_from_module = all_symptoms_present(anom_b, module=module)

                    if req_a_mod < req_b_mod and b_fires_from_module:
                        suppressed_by_b = True
                        break

                if suppressed_by_b:
                    to_suppress.add(anom_a)
                    break

            else:
                # Fan ON: full sensor set comparison
                if required_sensors(anom_a) < required_sensors(anom_b):
                    to_suppress.add(anom_a)
                    break

    final_anomalies = flagged - to_suppress

    # --- 5. Build result dict, set group columns and Unknown Anomaly ---
    result = {a: 0 for a in anomalies_list}
    for anom_name in final_anomalies:
        if anom_name in result:
            result[anom_name] = 1

    for subsystem_name, subsystem_anomalies in ANOMALY_SUBSYSTEMS.items():
        result[subsystem_name] = int(any(result.get(a, 0) == 1 for a in subsystem_anomalies))

    # Unknown Anomaly: sensors are active but none are explained by any flagged known anomaly
    explained_sensors = set()
    for anom_name in final_anomalies:
        explained_sensors |= required_sensors(anom_name)

    known_anomaly_nodes = {a for a in anomalies_list
                            if a not in ("Unknown Anomaly", "Atmosphere Revitalization", "Atmosphere Control and Supply")}
    no_known_anomalies = not any(result.get(a, 0) == 1 for a in known_anomaly_nodes)
    unexplained_active = set(all_active.keys()) - explained_sensors
    result["Unknown Anomaly"] = int(no_known_anomalies and bool(unexplained_active))

    # NOTE: NEW CODE ON 09/16/2026
    # Hidden fault-isolation evidence: only activates alongside Unknown Anomaly, driven by which unexplained sensors are active.
    for node_name, sensor_names in FAULT_ISOLATION_HIDDEN_NODES.items():
        active_for_node = any(sensor_row.get(s, 0) >= 1 for s in sensor_names)
        result[node_name] = int(result["Unknown Anomaly"] == 1 and active_for_node)

    return result


def parse_simulation_ticks(data, anomaly_name, anomaly_tick, anomalies_list,
                          halo_anomaly=None, halo_sensors=None, second_anomaly=None, fan_status=None):
    """
    Parse tick snapshots from a single simulation run into row dicts.
    
    Args:
        data: JSON response from the simulation log endpoint
        anomaly_name: The anomaly to inject for this config (or None for baseline)
        anomaly_tick: The tick number at which the anomaly activates (or None)
        anomalies_list: Full list of anomaly names used in the Bayesian network
        halo_anomaly: Optional habitat-wide anomaly name to inject when
                      specified HALO sensors show off-nominal values
        halo_sensors: List of HALO sensor name substrings to check for symptoms
                      (e.g. ['ppCO2_HALO', 'Humidity_HALO'] for CDRA,
                       ['ppO2_HALO'] for bio filter)
    
    Returns:
        List of row dicts suitable for DataFrame construction
    """
    
    history = defaultdict(lambda: deque(maxlen=30))
    rows = []
    crew_death_tick = None # set once all crew are confirmed dead

    for idx, tick in enumerate(data.get('ticks', [])):
        tick_num = tick.get('tick', idx)
        modules_state = tick.get('modules', {})


        # --- Crew death detection ---
        # Find any CrewGroup module in this tick's snapshot and check O2Consumed.
        # kill() in CrewPerson.java sets O2Consumed = 0f; alive crew always > 0.
        if crew_death_tick is None:
            for mod_name, mod in modules_state.items():
                if mod.get('moduleType') == 'CrewGroup':
                    people = mod.get('properties', {}).get('crewPeople', [])
                    if people and all(p.get('O2Consumed', 1.0) == 0.0 for p in people):
                        crew_death_tick = tick_num
                        print(f"    ⚠️  Crew death detected in log at tick {tick_num} "
                              f"— truncating training data here")
                        break
 
        # Stop appending rows from the death tick onward
        if crew_death_tick is not None and tick_num >= crew_death_tick:
            break       
       
       
        sensor_row = {'tick': tick_num + NOMINAL_DATA_TICKS}

        param_names = []
        for mod_name, mod in modules_state.items():
            module_type = mod.get('moduleType', '')
            if "Sensor" in module_type:
                props = mod.get('properties', {})
                input_val = mod.get('input')
                if input_val is None:
                    if "_" in mod_name:
                        input_val = mod_name.split("_")[-1]
                    else:
                        input_val = ""
                base_name = f"{mod_name} ({input_val})"
                
                # Create two columns for split parameters
                high_param_name = f'high {base_name}'
                low_param_name = f'low {base_name}'
                # Create two columns for high/low (t-1) parameters
                prev_high_param_name = f'high {base_name} (t-1)'
                prev_low_param_name = f'low {base_name} (t-1)'

                param_names.extend([high_param_name, low_param_name, prev_high_param_name, prev_low_param_name])

                if 'value' in props:
                    # Get the monitoring result
                    if "monitoringResult" in props:
                        result = props["monitoringResult"]
                        # Map levels for high and low parameters
                        sensor_row[high_param_name] = (
                            2 if 'CRITICAL_HIGH' in result else
                            1 if 'WARNING_HIGH' in result else 0
                        )
                        sensor_row[low_param_name] = (
                            2 if 'CRITICAL_LOW' in result else
                            1 if 'WARNING_LOW' in result else 0
                        )

                        # Get t-30 (t-1) result
                        history_queue = history[base_name]
                        if len(history_queue) >= 30: # if length is 30, t-30 exists
                            t_minus_30_result = history_queue[0]
                            sensor_row[prev_high_param_name] = (
                                2 if 'CRITICAL_HIGH' in t_minus_30_result else
                                1 if 'WARNING_HIGH' in t_minus_30_result else 0
                            )
                            sensor_row[prev_low_param_name] = (
                                2 if 'CRITICAL_LOW' in t_minus_30_result else
                                1 if 'WARNING_LOW' in t_minus_30_result else 0
                            )
                        else:
                            sensor_row[prev_high_param_name] = 0
                            sensor_row[prev_low_param_name] = 0
                        # Append current result to history
                        history_queue.append(result)

                # Store all properties
                for prop_key, prop_val in props.items():
                    column_name = f"{base_name}_{prop_key}"
                    sensor_row[column_name] = prop_val

        # Define the fan status for the current simulation
        if fan_status is None or fan_status == 'on':
            sensor_row['Fan Status'] = 1
        elif fan_status == 'off':
            sensor_row['Fan Status'] = 0

        # Symptom-based anomaly injection
        # 1. Set hidden component = 1 at the malfunction tick, explicitly adding zeros to all other hidden component nodes
        active_components = set()
        if anomaly_name is not None and anomaly_tick is not None and tick_num is not None:
            if anomaly_name in ANOMALY_SYMPTOMS:
                comp = ANOMALY_SYMPTOMS[anomaly_name]["component"]
                sensor_row[comp] = int(tick_num >= anomaly_tick)
                active_components.add(ANOMALY_SYMPTOMS[anomaly_name]["component"])
            # For second_anomaly (e.g., default_leak sets both IHab and HALO)
            if second_anomaly is not None and second_anomaly in ANOMALY_SYMPTOMS:
                comp2 = ANOMALY_SYMPTOMS[second_anomaly]["component"]
                sensor_row[comp2] = int(tick_num >= anomaly_tick)
                active_components.add(ANOMALY_SYMPTOMS[second_anomaly]["component"])

        for anom_info in ANOMALY_SYMPTOMS.values():
            comp = anom_info["component"]
            if comp not in active_components:
                sensor_row[comp] = 0 # set non-faulty components to zero

        # 2. Identify anomalies based on symptoms and also if there is high ppco2 in ihab it triggers excess co2 ihab and similar for halo and emergency o2
        # And if ppo2 is low in ihab and halo and if ppco2 is high only in ihab, it would trigger bfs and also emergency o2 in halo but if ppco2 is also high in halo, then it only triggers bfs. similar for cdra
        resolved = resolve_anomalies_for_tick(sensor_row, fan_status, anomalies_list)
        sensor_row.update(resolved)

        # met_anomalies = []
        # for anom_name, anom_info in ANOMALY_SYMPTOMS.items():
        #     ihab_sensors = [i for i in anom_info["sensors"] if i[0].endswith("(IHab)")]
        #     halo_sensors = [i for i in anom_info["sensors"] if i[0].endswith("(HALO)")]

        #     if fan_status == 'off':
        #         subsets_to_check = [ihab_sensors]
        #     else:
        #         subsets_to_check = [anom_info["sensors"], ihab_sensors, halo_sensors]

        #     best_met_sensors = None
        #     for sensors_subset in subsets_to_check:
        #         if not sensors_subset:
        #             continue

        #         all_symptoms_met = all(
        #             sensor_row.get(sensor, 0) >= threshold
        #             for sensor, threshold in sensors_subset
        #         )
                
        #         if all_symptoms_met:
        #             # Keep the largest subset of symptoms that is met
        #             if best_met_sensors is None or len(sensors_subset) > len(best_met_sensors):
        #                 best_met_sensors = set(sensor for sensor, threshold in sensors_subset)
            
        #     if best_met_sensors:
        #         met_anomalies.append({
        #             'name': anom_name,
        #             'sensors': best_met_sensors
        #         })

        # # Ensure all anomaly columns exist with default 0
        # for anomaly in anomalies_list:
        #     sensor_row.setdefault(anomaly, 0)

        # # Filter out anomalies whose symptoms are a subset of another met anomaly
        # final_anomalies = []
        # for anom in met_anomalies:
        #     is_subset = False
        #     for other_anom in met_anomalies:
        #         if anom['name'] != other_anom['name']:
        #             # If this anomaly's sensors are a strict subset of another anomaly's sensors
        #             if anom['sensors'].issubset(other_anom['sensors']):
        #                 is_subset = True
        #                 break
        #     if not is_subset:
        #         final_anomalies.append(anom['name'])

        # for anom_name in final_anomalies:
        #     sensor_row[anom_name] = 1

        # # Ensure all anomaly columns exist with default 0
        # for anomaly in anomalies_list:
        #     sensor_row.setdefault(anomaly, 0)

        # # Set group columns based on active anomalies
        # for subsystem_name, subsystem_anomalies in ANOMALY_SUBSYSTEMS.items():
        #     sensor_row[subsystem_name] = int(any(
        #         sensor_row.get(a, 0) == 1 for a in subsystem_anomalies
        #     ))

        # # Check whether any known anomalies are present
        # no_known_anomalies = all(sensor_row[anomaly] != 1 for anomaly in anomalies_list)
        # # Check whether any parameter values are off-nominal
        # no_active_params = all(sensor_row.get(param, 0) == 0 for param in param_names)

        # if no_known_anomalies and not no_active_params:
        #     sensor_row['Unknown Anomaly'] = 1
        # else:
        #     sensor_row['Unknown Anomaly'] = 0

        # Only store if sensor values are found
        if len(sensor_row) > 1: # more than just tick
            rows.append(sensor_row)

    return rows


def run_simulation(server_url, config_path, num_ticks):
    """
    Start a simulation with the given config, advance it, and return the log data.
    
    Args:
        server_url: BioSim server URL
        config_path: Path to the .biosim config file
        num_ticks: Number of ticks to advance the simulation
    
    Returns:
        JSON log data from the simulation
    """
    # Read the config file
    with open(config_path, 'r') as f:
        biosim_xml = f.read()

    # Lock for the start call
    with _start_lock:
        # Submit the XML config and get a simulation ID
        resp = requests.post(
            f'{server_url}/api/simulation/start',
            headers={'Content-Type': 'text/plain'},
            data=biosim_xml
        )
        if not resp.ok:
            raise RuntimeError(f"Failed to start simulation for {config_path}: {resp.status_code} {resp.text}")
        simID = resp.json()['simId']
        print(f"    Started {os.path.basename(config_path)} → simID={simID}")


    # Determine which CrewGroup module name to watch by parsing the config XML.
    # Looks for <CrewGroup moduleName="..."> — falls back to None (no early stop).
    import xml.etree.ElementTree as ET
    crew_module_name = None
    try:
        ns = {'b': 'http://www.traclabs.com/biosim'}
        root = ET.fromstring(biosim_xml)
        cg = root.find('.//b:CrewGroup', ns)
        if cg is not None:
            crew_module_name = cg.get('moduleName')
    except Exception:
        pass  # non-fatal — early-stop just won't trigger


    # Tick advancement runs outside the lock
    for i in range(num_ticks):
        resp = requests.post(f'{server_url}/api/simulation/{simID}/tick')
        time.sleep(0.02) # small delay to avoid overwhelming the server

        # Poll crew status every 10 ticks to detect death without hammering the server.
        # O2Consumed == 0.0 for every crew member is the reliable death signal
        # (kill() sets it to 0f explicitly in CrewPerson.java).
        if crew_module_name and i % 10 == 0:
            try:
                mod_resp = requests.get(
                    f'{server_url}/api/simulation/{simID}/modules/{crew_module_name}',
                    timeout=2
                )
                if mod_resp.ok:
                    crew_data = mod_resp.json()
                    people = crew_data.get('properties', {}).get('crewPeople', [])
                    if people and all(p.get('O2Consumed', 1.0) == 0.0 for p in people):
                        print(f"    ⚠️  All crew dead at tick {i} — stopping early "
                              f"({num_ticks - i} ticks remaining)")
                        break
            except Exception:
                pass  # non-fatal — continue ticking if poll fails        


    resp = requests.get(f'{server_url}/api/simulation/{simID}/log')
    if not resp.ok:
        raise RuntimeError(f"Failed to get simulation log for {config_path}: {resp.status_code} {resp.text}")

    data = resp.json()
    return data


def run_single_config(config_name, config_info, server_url, num_ticks):
    """
    Run a single simulation config end-to-end: simulate + parse.
    Returns (config_name, rows, elapsed_seconds).
    Thread-safe — no shared mutable state.
    """
    t0 = time.time()
    config_path = os.path.join(CONFIG_DIR, config_name)
    anomaly_name = config_info['anomaly']
    anomaly_tick = config_info['tick']
    fan_status = config_info.get('fan_status', None)
    halo_anomaly = config_info.get('halo_anomaly', None)
    halo_sensors = config_info.get('halo_sensors', None)
    second_anomaly = config_info.get('second_anomaly', None)

    data = run_simulation(server_url, config_path, num_ticks)
    rows = parse_simulation_ticks(data, anomaly_name, anomaly_tick, anomalies,
                                 halo_anomaly=halo_anomaly, halo_sensors=halo_sensors,
                                 second_anomaly=second_anomaly, fan_status=fan_status)
    
    # Prepend hardcoded nominal data before the anomaly rows
    nominal_rows = generate_nominal_rows(NOMINAL_DATA_TICKS, fan_status=fan_status)
    all_config_rows = nominal_rows + rows
    elapsed = time.time() - t0
    return config_name, all_config_rows, elapsed


def get_ordered_bn_columns(all_nodes):
    sensors = ['ppCO2', 'ppO2', 'Humidity', 'Total_Cabin_Pressure']
    locations = ['HALO', 'IHab']
    param_nodes_ordered = []
    for sensor in sensors:
        for loc in locations:
            low = next((n for n in all_nodes if f'low {sensor} ({loc})' in n and '(t-1)' not in n), None)
            high = next((n for n in all_nodes if f'high {sensor} ({loc})' in n and '(t-1)' not in n), None)
            if low: param_nodes_ordered.append(low)
            if high: param_nodes_ordered.append(high)
    anomaly_nodes_ordered = [n for n in anomalies if n in all_nodes]
    hidden_nodes_ordered = [n for n in all_nodes if '[HIDDEN]' in n]
    other_nodes_ordered = [
        n for n in all_nodes if n not in param_nodes_ordered
                                 and n not in anomaly_nodes_ordered
                                 and n not in hidden_nodes_ordered
    ]
    return param_nodes_ordered + anomaly_nodes_ordered + hidden_nodes_ordered + other_nodes_ordered


# Run simulation with threads
def run_all_simulations_threaded(max_workers, num_ticks, server_url=SERVER_URL):
    """
    Run all configs in parallel using ThreadPoolExecutor.
    Returns (all_rows, total_elapsed, per_config_times).
    """
    all_rows = []
    per_config_times = {}

    t_total_start = time.time()

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {
            executor.submit(run_single_config, name, info, server_url, num_ticks): name
            for name, info in CONFIG_ANOMALY_MAP.items()
        }

        for future in as_completed(futures):
            config_name = futures[future]
            try:
                name, rows, elapsed = future.result()
                per_config_times[name] = elapsed
                all_rows.extend(rows)
                print(f"  [Thread] {name}: {len(rows)} rows in {elapsed:.2f}s")
            except Exception as e:
                per_config_times[config_name] = -1
                print(f"  [Thread] ERROR {config_name}: {e}")

    total_elapsed = time.time() - t_total_start
    return all_rows, total_elapsed, per_config_times


# Run simulation without threads
def run_all_simulations_sequential(num_ticks, server_url=SERVER_URL):
    """
    Run all configs sequentially (baseline for comparison).
    Returns (all_rows, total_elapsed, per_config_times).
    """
    all_rows = []
    per_config_times = {}

    t_total_start = time.time()

    for config_name, config_info in CONFIG_ANOMALY_MAP.items():
        try:
            name, rows, elapsed = run_single_config(config_name, config_info, server_url, num_ticks)
            per_config_times[name] = elapsed
            all_rows.extend(rows)
            print(f"  [Sequential] {name}: {len(rows)} rows in {elapsed:.2f}s")
        except Exception as e:
            per_config_times[config_name] = -1
            print(f"  [Sequential] ERROR {config_name}: {e}")

    total_elapsed = time.time() - t_total_start
    return all_rows, total_elapsed, per_config_times


