# Add noise to labeled data
def add_anomaly_label_noise_df(df, noise_rate=0.01, seed=42):
    """
    Flip exactly noise_rate of all positive anomaly/Unknown Anomaly
    labels from 1 to 0.
    """

    rng = np.random.default_rng(seed)

    noisy_columns = [
        a for a in anomalies
        if a not in {
            "Atmosphere Revitalization",
            "Atmosphere Control and Supply"
        }
        and a in df.columns
    ]

    # Boolean mask of all positive anomaly labels
    positive_mask = df[noisy_columns].eq(1)

    # Get locations of all positive labels
    positive_locations = np.argwhere(positive_mask.to_numpy())

    total_positive = len(positive_locations)

    if total_positive == 0:
        print("No positive anomaly labels found; no noise added.")
        return df

    num_to_flip = int(round(total_positive * noise_rate))

    selected = rng.choice(
        total_positive,
        size=num_to_flip,
        replace=False
    )

    # Flip selected labels
    for idx in selected:
        row_idx, col_idx = positive_locations[idx]
        column = noisy_columns[col_idx]
        df.iat[row_idx, df.columns.get_loc(column)] = 0

    print(f"Added anomaly label noise: {num_to_flip}/{total_positive} ({100 * num_to_flip / total_positive:.2f}%) positive labels flipped 1 → 0")

    return df


# Function for parameter learning and saving the CPDs to a file
def run_parameter_learning(all_rows, output_prefix="threaded"):
    """Run Bayesian Estimator parameter learning on collected simulation data."""
    from pgmpy.estimators import BayesianEstimator as BE

    t0 = time.time()

    df_full = pd.DataFrame(all_rows)
    print(f"\nFull dataset shape: {df_full.shape}")

    # Add noise to 1% of anomaly labels
    df_full = add_anomaly_label_noise_df(df_full, noise_rate=0.01, seed=42)

    # Save DataFrame for parameter learning
    full_filepath = f'biosim_full_{output_prefix}.csv'
    df_full.to_csv(full_filepath, index=False)
    print(f'Saved full biosim dataset to {full_filepath}')

    # Extract relevant columns for parameter learning dataset
    ordered_cols = get_ordered_bn_columns(model.nodes())
    df_training = df_full[[col for col in ordered_cols if col in df_full.columns]]
    print(f'Training dataset shape: {df_training.shape}')

    training_filepath = f'biosim_training_dataset_{output_prefix}.csv'
    df_training.to_csv(training_filepath, index=False)
    print(f'Saved training dataset to {training_filepath}')

    # Create samples from biosim training dataset
    samples = df_training

    new_model = BayesianNetwork(ebunch = model.edges())

    state_names = {}
    for node in new_model.nodes():
        if '[HIDDEN]' in node or node in anomalies or node == 'Fan Status':
            state_names[node] = [0, 1]
        else:
            state_names[node] = [0, 1, 2]

    estimator = BE(new_model, samples, state_names=state_names)

    # If different prior strengths are desired for different anomalies in the network (for example,
    # having greater confidence in a CDRA failure prior than an Unknown Anomaly), a library of node
    # priors can be set up here
    PRIOR_STRENGTH = 5

    def compute_alpha(node, model, state_names):
        """
        Compute the per-node alpha so that the total prior pseudocounts = PRIOR_STRENGTH,
        regardless of the CPD dimensions
        """
        parents = model.get_parents(node)
        # Find the cardinality of the node in question
        k = len(state_names[node])

        if not parents:
            # Root node: CPD is just k states
            return PRIOR_STRENGTH / k
        else:
            # Compute the number of parent combinations for a given child node
            num_parent_combos = prod(len(state_names[p]) for p in parents)
            # Total CPD entries = k * num_parent_combos
           
            # if node == '[HIDDEN] BFS Component' or node == '[HIDDEN] CDRA Failure Component':
            #     # print(f'Alpha for {node}: {PRIOR_STRENGTH / (k * num_parent_combos)}')
            #     return PRIOR_STRENGTH / (2 * k * num_parent_combos)
            # else:
            return PRIOR_STRENGTH / (k * num_parent_combos)
        
    # Build the pseudo_counts dictionary expected by BayesianEstimator
    # Updated to have the correct shape for each specific node
    def build_node_pseudo_counts(node, model, state_names, alpha):
        """
        Build pseudo_counts in the shape pgmpy expects for a given node:
        (k, num_parent_combos) as a list of lists
        """
        parents = model.get_parents(node)
        k = len(state_names[node])

        if not parents:
            num_parent_combos = 1
        else:
            num_parent_combos = prod(len(state_names[p]) for p in parents)

        # Shape: (k, num_parent_combos) — each row is a state, each col is a parent combo
        return [[alpha] * num_parent_combos for _ in range(k)]        

    # Store learned nodes to determine which nodes need to be learned from data
    known_nodes = {cpd.variable for cpd in known_cpds}
    nodes_to_learn = [n for n in new_model.nodes if n not in known_nodes]

    learned_cpds = []
    for node in nodes_to_learn:        
        alpha = compute_alpha(node, new_model, state_names)
        # print(f'alpha: {alpha}')
        node_pseudo_counts = build_node_pseudo_counts(node, new_model, state_names, alpha)

        # Use .estimate_cpd method instead of .get_parameters as we are learning only a subset of the network's CPDs
        cpd = estimator.estimate_cpd(
            node,
            prior_type='dirichlet',
            pseudo_counts=node_pseudo_counts) # can update pseudo_counts dictionary if priors too uniform
        
        cpd.values = np.round(cpd.values, decimals=4)
        # Renormalize along axis 0 (each column of parent combinations sums to 1)
        # NOTE: Confirm that the follow normalization does not introduce any issues
        col_sums = cpd.values.sum(axis=0, keepdims=True)
        cpd.values = cpd.values / col_sums
        cpd.values = np.round(cpd.values, decimals=4)  # re-round after normalizing
    
        learned_cpds.append(cpd)

    for cpd in learned_cpds:
        print(cpd)

    cpds_filepath = os.path.join(current_dir, 'training_data', f'all_cpds_{output_prefix}.txt')

    with open(cpds_filepath, 'w') as f:
        f.write("=== Learned CPDs ===\n\n")
        for cpd in learned_cpds:
            # f.write(str(cpd))
            # f.write('\n\n')
            f.write(f"Variable: {cpd.variable}\n")
            f.write(f"Parents: {cpd.variables[1:]}\n")
            f.write(f"Values:\n{cpd.get_values()}\n\n")
        f.write("=== Known CPDs ===\n\n")
        for cpd in known_cpds:
            f.write(str(cpd))
            f.write('\n\n')
            # f.write(f"Variable: {cpd.variable}\n")
            # f.write(f"Parents: {cpd.variables[1:]}\n")
            # f.write(f"Values:\n{cpd.get_values()}\n\n")
    print(f'Saved CPDs to {cpds_filepath}')

    # Add learned CPDs to known deterministic CPDs previously defined
    new_model.add_cpds(*learned_cpds, *known_cpds)
    print('Model valid:', new_model.check_model())

    # Save the model
    model_filepath = os.path.join(current_dir, 'model', 'learned_model.pkl')
    with open(model_filepath, 'wb') as f:
        pickle.dump(new_model, f)
    print(f'Saved trained model to {model_filepath}')

    be_elapsed = time.time() - t0
    print(f'Parameter learning took {be_elapsed:.2f}s')
    return be_elapsed


def start_biosim_server():
    """Start the BioSim Java server and wait for it to be ready."""
    jar_path = os.path.join(_mars_repos_dir, 'biosim', 'target', 'biosim-2.0.0-jar-with-dependencies.jar')
    proc = subprocess.Popen(['java', '-jar', jar_path, '--writeTicks'])
    print('Starting BioSim server...')

    for attempt in range(30):
        try:
            resp = requests.get(f'{SERVER_URL}/api/simulation', timeout=2)
            if resp.ok:
                print(f'BioSim server ready after {attempt + 1}s')
                return proc
        except requests.ConnectionError:
            pass
        time.sleep(1)

    print('Warning: BioSim server may not be ready, proceeding anyway...')
    return proc


def stop_biosim_server(proc):
    """Terminate the BioSim server."""
    if proc:
        proc.terminate()
        proc.wait(timeout=10)
        print('BioSim server stopped.')


# Testing: run tests across different thread counts and tick counts
def run_testing(worker_counts, tick_counts):
    """
    Run simulations across all combinations of worker_counts and tick_counts.
    Collects timing data and prints a summary table.
    """
    results = []  # list of dicts: {workers, ticks, total_time, sim_time, be_time, rows}

    for num_ticks in tick_counts:
        for num_workers in worker_counts:
            label = f"sequential" if num_workers == 1 else f"{num_workers} threads"
            print(f"\n{'='*70}")
            print(f"  TESTING: {label}, {num_ticks} ticks")
            print(f"{'='*70}")

            server_proc = start_biosim_server()

            try:
                t_run_start = time.time()

                if num_workers == 1:
                    all_rows, sim_time, per_config = run_all_simulations_sequential(num_ticks)
                else:
                    all_rows, sim_time, per_config = run_all_simulations_threaded(num_workers, num_ticks)

                num_rows = len(all_rows)
                print(f"\n  Simulation phase: {sim_time:.2f}s, {num_rows} rows collected")

                # Run BE parameter learning
                if num_rows > 0:
                    be_time = run_parameter_learning(all_rows, output_prefix=f"w{num_workers}_t{num_ticks}")
                else:
                    be_time = 0.0
                    print("  Skipping BE learning (no data)")

                total_time = time.time() - t_run_start

                results.append({
                    'workers': num_workers,
                    'ticks': num_ticks,
                    'sim_time': sim_time,
                    'be_time': be_time,
                    'total_time': total_time,
                    'rows': num_rows,
                    'configs': len(CONFIG_ANOMALY_MAP),
                })

            except Exception as e:
                print(f"  TESTING ERROR: {e}")
                results.append({
                    'workers': num_workers,
                    'ticks': num_ticks,
                    'sim_time': -1,
                    'be_time': -1,
                    'total_time': -1,
                    'rows': 0,
                    'configs': len(CONFIG_ANOMALY_MAP),
                })
            finally:
                stop_biosim_server(server_proc)
                time.sleep(3) # give port time to free up

    # Print summary table
    print(f"\n\n{'='*90}")
    print(f"  TESTING RESULTS SUMMARY")
    print(f"{'='*90}")
    print(f"{'Workers':>8} | {'Ticks':>6} | {'Sim Time':>10} | {'BE Time':>10} | {'Total Time':>11} | {'Rows':>7} | {'Speedup':>8}")
    print(f"{'-'*8}-+-{'-'*6}-+-{'-'*10}-+-{'-'*10}-+-{'-'*11}-+-{'-'*7}-+-{'-'*8}")

    # Sequential times for speedup calculation
    baseline_times = {}
    for r in results:
        if r['workers'] == 1 and r['sim_time'] > 0:
            baseline_times[r['ticks']] = r['sim_time']

    for r in results:
        sim_str = f"{r['sim_time']:.2f}s" if r['sim_time'] >= 0 else "ERROR"
        be_str = f"{r['be_time']:.2f}s" if r['be_time'] >= 0 else "ERROR"
        total_str = f"{r['total_time']:.2f}s" if r['total_time'] >= 0 else "ERROR"

        baseline = baseline_times.get(r['ticks'], None)
        if baseline and r['sim_time'] > 0:
            speedup = f"{baseline / r['sim_time']:.2f}x"
        elif r['workers'] == 1 and r['sim_time'] > 0:
            speedup = "1.00x"
        else:
            speedup = "N/A"

        print(f"{r['workers']:>8} | {r['ticks']:>6} | {sim_str:>10} | {be_str:>10} | {total_str:>11} | {r['rows']:>7} | {speedup:>8}")

    print(f"{'='*90}")

    # Save results to CSV
    results_df = pd.DataFrame(results)
    results_filepath = 'testing_results.csv'
    results_df.to_csv(results_filepath, index=False)
    print(f"\nTesting results saved to {results_filepath}")

    return results


# Main function to run the simulation given thread count and tick count
def run_single(num_workers, num_ticks):
    """Run a single simulation pass with the given thread count and tick count."""
    server_proc = start_biosim_server()

    try:
        if num_workers == 1:
            all_rows, sim_time, per_config = run_all_simulations_sequential(num_ticks)
        else:
            all_rows, sim_time, per_config = run_all_simulations_threaded(num_workers, num_ticks)

        print(f"\n{'='*60}")
        print(f"  Simulation completed: {sim_time:.2f}s, {len(all_rows)} rows")
        print(f"{'='*60}")

        if len(all_rows) > 0:
            be_time = run_parameter_learning(all_rows, output_prefix=f"w{num_workers}_t{num_ticks}")
            print(f"\n  Total time: sim={sim_time:.2f}s + learning={be_time:.2f}s = {sim_time + be_time:.2f}s")
        elif len(all_rows) == 0:
            print("\n  No rows collected — skipping parameter learning")

    finally:
        stop_biosim_server(server_proc)


def main():
    parser = argparse.ArgumentParser(
        description="Threaded BioSim simulation runner with testing"
    )
    parser.add_argument('--workers', type=int, default=4,
                        help='Number of threads for simulation (default: 4)')
    parser.add_argument('--ticks', type=int, default=1000,
                        help='Number of simulation ticks (default: 1000)')
    parser.add_argument('--testing', action='store_true',
                        help='Run a full simulation across different thread and tick combinations')
    parser.add_argument('--testing-workers', type=str, default='1,2,4,6,8,9,10,12,14,16,18',
                        help='Comma-separated thread counts (default: 1,2,4,6,8,10,12,14,16)')
    parser.add_argument('--testing-ticks', type=str, default='500,1000',
                        help='Comma-separated tick counts (default: 500,1000)')


    args = parser.parse_args()

    if args.testing:
        worker_counts = [int(x.strip()) for x in args.testing_workers.split(',')]
        tick_counts = [int(x.strip()) for x in args.testing_ticks.split(',')]
        print(f"Running testing: workers={worker_counts}, ticks={tick_counts}")
        print(f"Total runs: {len(worker_counts) * len(tick_counts)}")
        run_testing(worker_counts, tick_counts)
    else:
        print(f"Running with {args.workers} worker(s), {args.ticks} ticks")
        run_single(args.workers, args.ticks)


if __name__ == '__main__':
    main()